python3 -c "
import numpy as np, json, itertools
def read(f):
    L=open(f).read().split('\n'); n=int(L[0]); 
    sy=[];xyz=[]
    for l in L[2:2+n]:
        p=l.split(); sy.append(p[0]); xyz.append([float(x) for x in p[1:4]])
    return sy,np.array(xyz)
sy,X=read('opt1.xyz')
i=json.load(open('idx.json'))
names={i['Si']:'Si',i['Np']:'Np',i['Otf']:'Otf',i['P']:'P',i['Hrh']:'H'}
Rh=i['Rh']
for a in names: print(names[a], round(np.linalg.norm(X[a]-X[Rh]),2))
for a,b in itertools.combinations(names,2):
    v1=X[a]-X[Rh]; v2=X[b]-X[Rh]
    print(names[a],names[b],round(np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2))),1))
print('Hn-Nq', round(np.linalg.norm(X[i['Hn']]-X[i['Nq']]),2))
print('Np-Hn', round(np.linalg.norm(X[i['Hn']]-X[i['Np']]),2))
"
